INSERT INTO `v1_8cf8a922806583f4b52a8ceff4938d59f1e2ed5388943471ea3c37fc5648dc82` VALUES (1.21875, 1.21875, "サマー衣装のチカがかわいく描かれたピンバッジ。限定バージョ\nンのデザインはサマーライブ参加の証。夏を満喫中のチカの表情\nが魅力的な一品。", "チカのサマーピンバッジ", 3, 1, 11506);
